        halKey: tmHal[0] && tmHal[0].key, halCtl: tmHalCtl.length,
        frameOk: /tm-frame/.test(frameHtml) && /التَّحْضِيض/.test(frameHtml),
        cssOk: /\.shart-frame\.tm-frame/.test(css),
