      const r9 = an('أَنَا أَفْعَلُ كَذَا أَيُّهَا الرَّجُلُ');
      const g131 = GRAMMAR['al-nahy-wa-wujuhuh'], g132 = GRAMMAR['jawab-al-talab'],
            g133 = GRAMMAR['ighra-wa-ikhtisas'];
