      await page.evaluate(() => { conjState.lab = 'qawaid'; conjState.qawaid = 'لَمْ يَكْتُبُونَ الدَّرْسَ'; renderLabBody(); });
      await page.waitForSelector('#qawaidOut .qw-row.bad', { timeout: 10000 });
