    if (r.tamthil2 !== 'none' || r.qawl !== 'none') throw new Error('كَالْكَيْفِيَّاتِ / كَقَوْلِهِ are no likening — ' + r.tamthil2 + ' / ' + r.qawl);
    eq('khadd', 'harf|خَدُّهُ|كَالْوَرْدِ|∅|mufrad/mufrad/null');
