               notes: ['ilm-al-bayan', 'arkan-al-tashbih'].filter(k => !GRAMMAR[k] || GRAMMAR[k].group !== 'bayan'), group: REF_GROUPS.some(g => g.id === 'bayan'), baligh: kinds.includes('baligh'),
