      w = W('وَأَحْسَنُ السَّجْعِ مَا تَسَاوَتْ قَرَائِنُهُ'); pin('وَأَحْسَنُ السَّجْعِ: the elative at the head', w[0] === N('وَأَحْسَنُ') && w[1] === N('السَّجْعِ'));
