      w = W('فَأَمَّا الْيَتِيمَ فَلَا تَقْهَرْ'); pin('أَمَّا الْيَتِيمَ فَلَا تَقْهَرْ: the fronted object of the prohibition', w[1] === N('الْيَتِيمَ'));
