      for (const st of STORIES) for (const c of st.chapters) for (const sn of c.sentences || []) { const T = sn.tokens || [];
        const need = T.map((t, i) => (t.pos === 'verb' && vOf((t.irab || {}).ar)) ? i : -1).filter(i => i >= 0); if (!need.length) continue;
        let rows; try { rows = SentenceAnalyzer.analyze(T.map(t => t.s.full).join(' ')); } catch (e) { continue; } if (!rows || rows.length !== T.length) continue;
        for (const i of need) { let bv = null; try { bv = Murib.binaVowel(rows[i]); } catch (e) {} const e = bv && vOf(bv.ar); if (!e) continue; if (e === vOf(T[i].irab.ar)) agree++; else dis++; } }
      return { cases, agree, dis };
